import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiStation","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/index.md","filePath":"en/modules/station/index.md","lastUpdated":0}`),a={name:`en/modules/station/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakistation" tabindex="-1">EmakiStation <a class="header-anchor" href="#emakistation" aria-label="Permalink to “EmakiStation”">​</a></h1><p>EmakiStation is the general-purpose crafting station module of the Emaki series. It turns &quot;submit materials against a recipe, queue the craft, collect the output later&quot; into a configurable GUI station, and additionally ships a fully independent dismantling station.</p><p>The crafting side is a three-page window (recipe catalog → material preview → craft queue) with a serial queue. Materials are spent from a merged inventory-plus-warehouse pool, with the warehouse participating once EmakiStorage is installed. Outputs are routed to the warehouse or the inventory; when neither can accept them the entry becomes pending-claim, and nothing is ever dropped or destroyed.</p><h2 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to “Basic Information”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.1.0</code></td></tr><tr><td>API coordinates</td><td><code>emaki.jiuwu.craft:emaki-station-api:1.1.0</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.station.EmakiStationPlugin</code></td></tr><tr><td>Main command</td><td><code>/emakistation</code></td></tr><tr><td>Aliases</td><td><code>/estation</code>, <code>/est</code></td></tr><tr><td>Required dependency</td><td>EmakiCoreLib</td></tr><tr><td>Optional dependencies</td><td>EmakiStorage, PlaceholderAPI</td></tr><tr><td>Descriptor baseline</td><td><code>api-version: &quot;1.21.8&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>Main permissions</td><td><code>emakistation.use</code> (default true), <code>emakistation.purchase</code> (default true), <code>emakistation.dismantle</code> (default true), <code>emakistation.reload</code> (op), <code>emakistation.debug</code> (op), <code>emakistation.admin</code> (op)</td></tr></tbody></table><p>The POM/runtime/API and default <code>config.yml</code> version is <code>1.1.0</code>. The internal <code>AppConfig.CURRENT_VERSION = &quot;1.0.2&quot;</code> is a configuration-migration structure constant; the two serve different purposes and must not be conflated.</p><h2 id="feature-pages" tabindex="-1">Feature Pages <a class="header-anchor" href="#feature-pages" aria-label="Permalink to “Feature Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands and Permissions</a></td><td>The 9 subcommands, 6 permission nodes and two access-permission prefixes of <code>/emakistation</code>.</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>The <code>queue</code>, <code>limits</code>, <code>storage</code>, <code>persistence</code> and <code>gui</code> sections of <code>config.yml</code>.</td></tr><tr><td><a href="./stations.html">Station Definitions</a></td><td>Layouts, permissions, queue parameters, material channels and output routing in <code>stations/&lt;id&gt;.yml</code>.</td></tr><tr><td><a href="./recipes.html">Recipe Definitions</a></td><td>Ownership, materials, outputs, duration, currency cost and the two condition gates in <code>recipes/&lt;recipe&gt;.yml</code>.</td></tr><tr><td><a href="./queue.html">Craft Queue</a></td><td>The three sources of queue length, serial progression, cancellation refunds and the pending-claim state.</td></tr><tr><td><a href="./queue-costs.html">Paid Queue Slots</a></td><td>The tiers, per-slot pricing and three switches of <code>queue_costs.yml</code>.</td></tr><tr><td><a href="./dismantle.html">Dismantling</a></td><td>Independent dismantle stations plus <code>input_source</code>, <code>rolls</code> and weighted <code>pool</code> rolling.</td></tr><tr><td><a href="./gui.html">GUI Templates</a></td><td>Slot types of the four GUI templates and the &quot;<code>type:</code> must be explicit&quot; rule.</td></tr><tr><td><a href="./api.html">API and Integration</a></td><td>The facade, query and operation layers of <code>emaki-station-api</code> and their thread constraints.</td></tr><tr><td><a href="./events.html">Event API</a></td><td><code>StationCraftSubmitEvent</code>, <code>StationCraftCancelEvent</code> and <code>StationCraftCompletedEvent</code>.</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core Capabilities”">​</a></h2><ul><li><strong>Unordered set matching:</strong> a recipe only looks at material kinds and totals, never at placement. There is no shaped concept. <code>item_sources</code> is an &quot;any of these&quot; set whose amount is counted across the whole set, so 30 coal plus 34 charcoal satisfies a requirement of 64.</li><li><strong>Merged inventory and warehouse supply:</strong> when both channels are enabled, materials come from a merged pool spent inventory-first. Players see no channel toggle; the &quot;owned&quot; figure in the window is already the combined total.</li><li><strong>Serial single-line queue:</strong> one player has one queue per station, and only the head advances. <code>waiting</code> and <code>running</code> occupy queue length while <code>pending_claim</code> does not.</li><li><strong>Three sources of queue length:</strong> the base length, the <code>emakistation.queue.&lt;n&gt;</code> permission tier, and paid purchases. The tier <strong>replaces</strong> the base length, purchased slots <strong>stack</strong> on top, and the result is clamped by <code>max_length</code>.</li><li><strong>Outputs are never lost:</strong> when every configured target is full, the entry turns into pending-claim and waits for <code>/emakistation claim</code> or the in-window button.</li><li><strong>Dismantling is fully independent:</strong> dismantle station ids are unrelated to crafting station ids and load from their own <code>stations_dismantle/</code> and <code>recipes_dismantle/</code> directories. It is not a fourth page of a crafting station.</li></ul><h2 id="file-layout" tabindex="-1">File Layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to “File Layout”">​</a></h2><p>After the server has run, EmakiStation mainly uses the following files:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStation/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ queue_costs.yml</span></span>
<span class="line"><span>├─ stations/</span></span>
<span class="line"><span>│  └─ blacksmith.yml</span></span>
<span class="line"><span>├─ recipes/</span></span>
<span class="line"><span>│  └─ example_recipe.yml</span></span>
<span class="line"><span>├─ stations_dismantle/</span></span>
<span class="line"><span>│  └─ example_dismantle_station.yml</span></span>
<span class="line"><span>├─ recipes_dismantle/</span></span>
<span class="line"><span>│  └─ example_dismantle_recipe.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ station_catalog.yml</span></span>
<span class="line"><span>│  ├─ station_preview.yml</span></span>
<span class="line"><span>│  ├─ station_queue.yml</span></span>
<span class="line"><span>│  └─ station_dismantle.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main configuration: queue defaults, capacity limits, warehouse channel, persistence, GUI throttling.</td></tr><tr><td><code>queue_costs.yml</code></td><td>Paid queue slot tiers. A business data file: released once when missing, never overwritten by version upgrades.</td></tr><tr><td><code>stations/&lt;id&gt;.yml</code></td><td>Crafting station definition. The file name matches <code>id</code>.</td></tr><tr><td><code>recipes/&lt;recipe&gt;.yml</code></td><td>Crafting recipe definition. One recipe per file; ownership is declared recipe-side via <code>station_ids</code>.</td></tr><tr><td><code>stations_dismantle/&lt;id&gt;.yml</code></td><td>Dismantle station definition, unrelated to crafting stations.</td></tr><tr><td><code>recipes_dismantle/&lt;recipe&gt;.yml</code></td><td>Dismantle recipe definition with an input item and a weighted output pool.</td></tr><tr><td><code>gui/*.yml</code></td><td>Four window templates: recipe catalog, material preview, craft queue, dismantle window.</td></tr><tr><td><code>lang/*.yml</code></td><td>Command, window, precheck and console messages.</td></tr></tbody></table><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><ol><li>Put <code>EmakiCoreLib-*.jar</code> and <code>EmakiStation-*.jar</code> into the server <code>plugins/</code> folder.</li><li>Do <strong>not</strong> put <code>emaki-station-api-*.jar</code> into <code>plugins/</code>; the API Jar is a compile-time dependency for developers only.</li><li>After the first start, review <code>plugins/EmakiStation/config.yml</code> and the example station <code>stations/blacksmith.yml</code>.</li><li>Open the example station:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation open blacksmith</span></span></code></pre></div><ol start="5"><li>Inspect your queue and claim outputs:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation queue</span></span>
<span class="line"><span>/emakistation claim</span></span></code></pre></div><ol start="6"><li>Reload after editing configuration:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation reload</span></span></code></pre></div><h2 id="usage-notes" tabindex="-1">Usage Notes <a class="header-anchor" href="#usage-notes" aria-label="Permalink to “Usage Notes”">​</a></h2><ul><li><code>channels.backpack</code> and <code>channels.storage</code> must not both be false, or the station is refused at load time. A station that opens but can never be used is worse than a startup error.</li><li><code>channels.default</code> is a retained key that <strong>no longer has any effect</strong>. Once the channels were merged there is no such thing as &quot;which channel you are on&quot;; it only remains so old configuration files do not report an unknown key.</li><li>Besides <code>storage.enabled: true</code>, the warehouse channel also requires EmakiStorage to provide the <code>emakistorage:atomic_batch</code> capability. Without it there is no fallback to withdrawing item by item, because that would make materials flash through the player&#39;s inventory.</li><li><code>progress_mode: offline</code> only means &quot;the timer keeps running&quot;, not &quot;delivery while offline&quot;. Entries that come due while the player is offline are merely due; settlement happens at their next login.</li><li>All three layout files (<code>layout</code>, <code>preview_layout</code>, <code>queue_layout</code>) must exist. A missing one raises <code>missing_layout</code> in the startup precheck.</li><li>Material allocation is greedy with no backtracking. When one item can satisfy several requirements it goes to the one declared first, which in rare cases makes a theoretically valid recipe fail to match. Splitting the recipe avoids it.</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};